package main

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"
)

var (
	serveRoot string
	authToken string
)

func init() {
	serveRoot = os.Getenv("SERVE_ROOT")
	if serveRoot == "" {
		log.Fatal("SERVE_ROOT environment variable required")
	}
	authToken = os.Getenv("AUTH_TOKEN")
	if authToken == "" {
		tokenBytes := make([]byte, 32)
		if _, err := rand.Read(tokenBytes); err != nil {
			log.Fatal("Failed to generate auth token")
		}
		authToken = hex.EncodeToString(tokenBytes)
		fmt.Fprintf(os.Stderr, "Generated auth token: %s\n", authToken)
	}
}

// validateAuth checks the Bearer token using constant-time comparison
func validateAuth(r *http.Request) bool {
	auth := r.Header.Get("Authorization")
	if !strings.HasPrefix(auth, "Bearer ") {
		return false
	}
	token := strings.TrimPrefix(auth, "Bearer ")
	return subtle.ConstantTimeCompare([]byte(token), []byte(authToken)) == 1
}

// sanitizePath cleans and validates the requested file path
func sanitizePath(baseDir, requestedPath string) (string, error) {
	// Step 1: Reject any path containing null bytes
	if strings.ContainsRune(requestedPath, 0) {
		return "", fmt.Errorf("invalid path")
	}

	// Step 2: Clean the path to resolve . and ..
	cleaned := filepath.Clean(requestedPath)

	// Step 3: Reject any path that still contains ..
	if strings.Contains(cleaned, "..") {
		return "", fmt.Errorf("path traversal detected")
	}

	// Step 4: Ensure no leading slash (relative path only)
	cleaned = strings.TrimPrefix(cleaned, "/")

	// Step 5: Reject empty paths
	if cleaned == "" || cleaned == "." {
		return "", fmt.Errorf("empty path")
	}

	// Step 6: Join with base directory
	fullPath := filepath.Join(baseDir, cleaned)

	// Step 7: Resolve to absolute and verify containment
	absBase, err := filepath.Abs(baseDir)
	if err != nil {
		return "", err
	}
	// Ensure absBase ends with separator for prefix check
	if !strings.HasSuffix(absBase, string(filepath.Separator)) {
		absBase += string(filepath.Separator)
	}

	absFull, err := filepath.Abs(fullPath)
	if err != nil {
		return "", err
	}

	if !strings.HasPrefix(absFull+string(filepath.Separator), absBase) && absFull != strings.TrimSuffix(absBase, string(filepath.Separator)) {
		if !strings.HasPrefix(absFull, absBase) {
			return "", fmt.Errorf("path escapes base directory")
		}
	}

	return fullPath, nil
}

// handleFileDownload serves files from the configured root
func handleFileDownload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	if !validateAuth(r) {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	// r.URL.Path is already decoded by net/http
	// Do NOT double-decode to prevent double-encoding attacks
	requestPath := strings.TrimPrefix(r.URL.Path, "/files/")

	// Sanitize and validate the path
	safePath, err := sanitizePath(serveRoot, requestPath)
	if err != nil {
		http.Error(w, "Access denied", http.StatusForbidden)
		return
	}

	// Resolve symlinks and re-verify
	realPath, err := filepath.EvalSymlinks(safePath)
	if err != nil {
		if os.IsNotExist(err) {
			http.Error(w, "Not found", http.StatusNotFound)
		} else {
			http.Error(w, "Internal error", http.StatusInternalServerError)
		}
		return
	}

	// Re-verify after symlink resolution
	absBase, _ := filepath.Abs(serveRoot)
	if !strings.HasPrefix(realPath, absBase+string(filepath.Separator)) && realPath != absBase {
		http.Error(w, "Access denied", http.StatusForbidden)
		return
	}

	// Check file exists and is a regular file
	info, err := os.Stat(realPath)
	if err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}

	if info.IsDir() {
		http.Error(w, "Cannot download directories", http.StatusBadRequest)
		return
	}

	// Serve the file
	f, err := os.Open(realPath)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer f.Close()

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=%q", filepath.Base(realPath)))
	io.Copy(w, f)
}

// handleFileUpload handles file uploads to the configured root
func handleFileUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPut {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	if !validateAuth(r) {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	// Limit upload size to 50MB
	r.Body = http.MaxBytesReader(w, r.Body, 50*1024*1024)

	// r.URL.Path is already decoded by net/http
	requestPath := strings.TrimPrefix(r.URL.Path, "/upload/")

	// Sanitize and validate
	safePath, err := sanitizePath(serveRoot, requestPath)
	if err != nil {
		http.Error(w, "Access denied", http.StatusForbidden)
		return
	}

	// For uploads, verify parent directory is within base
	parentDir := filepath.Dir(safePath)
	absBase, _ := filepath.Abs(serveRoot)
	absParent, _ := filepath.Abs(parentDir)
	if !strings.HasPrefix(absParent, absBase) {
		http.Error(w, "Access denied", http.StatusForbidden)
		return
	}

	// Ensure parent directory exists
	if err := os.MkdirAll(parentDir, 0750); err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}

	// Write the file with restrictive permissions
	f, err := os.OpenFile(safePath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0640)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer f.Close()

	if _, err := io.Copy(f, r.Body); err != nil {
		http.Error(w, "Upload failed", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, "File uploaded successfully")
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/files/", handleFileDownload)
	mux.HandleFunc("/upload/", handleFileUpload)

	server := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadTimeout:       30 * time.Second,
		ReadHeaderTimeout: 10 * time.Second,
		WriteTimeout:      120 * time.Second,
		IdleTimeout:       120 * time.Second,
	}

	log.Printf("Starting file server on :8080, serving from %s", serveRoot)
	log.Fatal(server.ListenAndServe())
}
